import{_ as t,o as n,c as o,a4 as r}from"./chunks/framework.DAD9IEko.js";const _=JSON.parse('{"title":"时间最优轨迹规划测验","description":"","frontmatter":{"date":"2026-06-13T00:00:00.000Z","section":"电机控制","chapter":"motion-control","chapterTitle":"运动控制","chapterOrder":30,"category":"运动控制","source":"motor","visibility":"public","title":"时间最优轨迹规划测验","tags":["motor-control"],"status":"learning","summary":"**问题:** 时间最优控制为什么一定是Bang-Bang控制？","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/motion-control/MC-TP-05-assessment.md","filePath":"content/motor/motion-control/MC-TP-05-assessment.md","lastUpdated":1783181958000}'),e={name:"content/motor/motion-control/MC-TP-05-assessment.md"};function s(g,a,i,m,l,u){return n(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="时间最优轨迹规划测验" tabindex="-1">时间最优轨迹规划测验 <a class="header-anchor" href="#时间最优轨迹规划测验" aria-label="Permalink to &quot;时间最优轨迹规划测验&quot;">​</a></h1><h3 id="第1题-较难-bang-bang控制必然性" tabindex="-1">第1题 [较难] - Bang-Bang控制必然性 <a class="header-anchor" href="#第1题-较难-bang-bang控制必然性" aria-label="Permalink to &quot;第1题 [较难] - Bang-Bang控制必然性&quot;">​</a></h3><p><strong>问题:</strong> 时间最优控制为什么一定是Bang-Bang控制？</p><p><strong>参考答案:</strong> 根据Pontryagin最大值原理，对于具有有界控制输入的线性系统，使性能指标J = ∫dt（即最小化时间）最小的最优控制，一定取控制约束的极值（上限或下限），而不会取中间值。直观理解：要最快到达目标，就应该&quot;全力加速&quot;或&quot;全力减速&quot;，任何&quot;部分用力&quot;都是在浪费时间。因此时间最优控制一定是Bang-Bang形式——控制量在+u_max和-u_max之间切换（对于运动控制即+a_max和-a_max）。唯一的例外是当状态到达约束边界时（如速度达到v_max），控制量取保持约束所需的值（a=0），这称为&quot;singular arc&quot;。</p><h3 id="第2题-困难-相平面切换曲线物理含义" tabindex="-1">第2题 [困难] - 相平面切换曲线物理含义 <a class="header-anchor" href="#第2题-困难-相平面切换曲线物理含义" aria-label="Permalink to &quot;第2题 [困难] - 相平面切换曲线物理含义&quot;">​</a></h3><p><strong>问题:</strong> 在相平面上，切换曲线的物理含义是什么？</p><p><strong>参考答案:</strong> 切换曲线是相平面(x, v)上的一条特殊曲线，它将相平面分为两个区域：切换到最大加速的区域和切换到最大减速的区域。物理含义：切换曲线上的每一点(x, v)表示&quot;如果当前处于该状态并以最大减速度制动，恰好能在目标位置停下&quot;。即切换曲线满足方程：v² = 2·a_max·|x - x_target|（从目标位置反推）。当系统状态在切换曲线&quot;上方&quot;（速度偏大），必须立即开始减速；在&quot;下方&quot;则可以继续加速。切换曲线是时间最优轨迹中加速度从+a_max切换到-a_max（或反之）的时刻对应的状态集合。考虑jerk约束时，切换曲线不再是简单的抛物线，而是由jerk过渡段修正的曲线，切换需要提前。</p><h3 id="第3题-困难-三级bang-bang与七段s曲线关系" tabindex="-1">第3题 [困难] - 三级Bang-Bang与七段S曲线关系 <a class="header-anchor" href="#第3题-困难-三级bang-bang与七段s曲线关系" aria-label="Permalink to &quot;第3题 [困难] - 三级Bang-Bang与七段S曲线关系&quot;">​</a></h3><p><strong>问题:</strong> 三级Bang-Bang（考虑jerk约束）与七段S曲线是什么关系？</p><p><strong>参考答案:</strong> 三级Bang-Bang控制（考虑jerk约束）和七段S曲线本质上是同一事物在不同视角下的描述。三级Bang-Bang指jerk取三个值：+j_max、0、-j_max，这恰好对应七段S曲线中加速度的变化规律：阶段1（jerk=+j_max，加速增加）、阶段2（jerk=0，匀加速）、阶段3（jerk=-j_max，加速减小）、阶段5（jerk=-j_max，减速增加）、阶段6（jerk=0，匀减速）、阶段7（jerk=+j_max，减速减小）。阶段4（匀速段）对应singular arc。两者关系：（1）时间最优的S曲线就是三级Bang-Bang控制的最优解；（2）S曲线的&quot;七段&quot;是三级Bang-Bang在运动学约束下的具体实现形式；（3）退化情况对应Bang-Bang控制中某些阶段时间为零（如未达到最大加速度就需切换）。</p><h3 id="第4题-较难-工程中不运行在约束边界的原因" tabindex="-1">第4题 [较难] - 工程中不运行在约束边界的原因 <a class="header-anchor" href="#第4题-较难-工程中不运行在约束边界的原因" aria-label="Permalink to &quot;第4题 [较难] - 工程中不运行在约束边界的原因&quot;">​</a></h3><p><strong>问题:</strong> 为什么实际工程中不直接运行在约束边界上？</p><p><strong>参考答案:</strong> 实际工程中不直接运行在约束边界上的原因：（1）模型不确定性——理论计算的a_max、j_max与实际值有偏差，运行在边界意味着没有裕量，任何超调都会违反约束；（2）参数变化——惯量随负载变化、摩擦随温度变化，边界值不是常数；（3）扰动抑制——运行在边界附近时，系统没有余力应对外部扰动（如突加负载），可能导致失步或超调；（4）安全余量——工业标准要求保留一定安全裕量（通常取约束的70%~90%），避免触发保护；（5）寿命考量——长期运行在极限工况会加速机械磨损和电机发热；（6）鲁棒性——边界运行对控制器性能要求极高，实际控制器带宽有限，跟踪边界轨迹会产生误差。因此工程中通常将约束值降额使用（如取理论值的80%作为规划约束）。</p>',13)])])}const p=t(e,[["render",s]]);export{_ as __pageData,p as default};
